-- Test cash corrections as the real service role in an isolated, rolled-back transaction.
begin;
create function pg_temp.check_change(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception '%',message; end if; end$$;
set local role service_role;
do $$
declare trainer private.cashbook_accounts; other private.cashbook_accounts; cashier private.cashbook_accounts;
 team uuid; result jsonb; booking jsonb; edit jsonb; original uuid; current_id uuid; prior_id uuid; cancellation jsonb;
begin
 select * into trainer from private.cashbook_accounts where username='jentm';
 select * into other from private.cashbook_accounts where username='schmo';
 select * into cashier from private.cashbook_accounts where username='barow';
 select id into team from public.social_teams where slug='u19-junioren';
 perform pg_temp.check_change(not has_function_privilege('anon','public.cashbook_change_request(uuid,jsonb)','execute') and
  not has_function_privilege('authenticated','public.cashbook_change_request(uuid,jsonb)','execute'),'Change RPC exposed to browser roles');
 booking:=jsonb_build_object('action','book','requestId',gen_random_uuid(),'direction','deposit','amountCents',10000,'confirmed',true,'evidenceHash',repeat('a',64));
 booking:=booking||jsonb_build_object('evidencePath',cashier.id::text||'/'||(booking->>'requestId')||'/photo');
 result:=public.cashbook_request(cashier.suite_user_id,booking);
 perform pg_temp.check_change(result->>'balanceCents'='10000','Seed deposit failed');
 booking:=jsonb_build_object('action','book','requestId',gen_random_uuid(),'direction','withdrawal','amountCents',5000,'confirmed',true,'teamId',team,'evidenceHash',repeat('b',64),'signatureHash',repeat('c',64),'note','Original');
 booking:=booking||jsonb_build_object('evidencePath',trainer.id::text||'/'||(booking->>'requestId')||'/photo','signaturePath',trainer.id::text||'/'||(booking->>'requestId')||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,booking);original:=(result->>'entryId')::uuid;
 perform pg_temp.check_change(result->>'balanceCents'='5000','Seed withdrawal failed');
 perform pg_temp.check_change((select created_by_user_id=trainer.suite_user_id from private.cashbook_entries where id=original),'Original JWT actor not retained');
 edit:=jsonb_build_object('action','edit','id',original,'requestId',gen_random_uuid(),'amountCents',7000,'teamId',team,'reason','Betrag falsch','note','Korrigiert','confirmed',true,'evidencePath',booking->>'evidencePath','evidenceHash',booking->>'evidenceHash','signatureHash',repeat('d',64));
 edit:=edit||jsonb_build_object('signaturePath',trainer.id::text||'/'||(edit->>'requestId')||'/signature');
 result:=public.cashbook_request(other.suite_user_id,edit);
 perform pg_temp.check_change(result->>'status'='403','Foreign trainer edited a booking');
 result:=public.cashbook_change_request(cashier.suite_user_id,edit);
 perform pg_temp.check_change(result->>'status'='403','Cashier can edit trainer withdrawal');
 result:=public.cashbook_request(trainer.suite_user_id,edit||jsonb_build_object('confirmed',false));
 perform pg_temp.check_change(result->>'status'='400','Unconfirmed change accepted');
 result:=public.cashbook_request(trainer.suite_user_id,edit-'signatureHash');
 perform pg_temp.check_change(result->>'status'='400','Unsigned change accepted');
 result:=public.cashbook_request(trainer.suite_user_id,edit||jsonb_build_object('teamId',(select id from public.social_teams where slug='u15-c1-junioren')));
 perform pg_temp.check_change(result->>'status'='403','Foreign team edit accepted');
 result:=public.cashbook_request(trainer.suite_user_id,edit||jsonb_build_object('amountCents',15000));
 perform pg_temp.check_change(result->>'status'='409' and private.cashbook_balance()=5000,'Correction overdraw accepted');
 result:=public.cashbook_request(trainer.suite_user_id,edit);
 current_id:=(result->>'entryId')::uuid;
 perform pg_temp.check_change(result->>'balanceCents'='3000','Increasing withdrawal did not debit only difference');
 perform pg_temp.check_change((select count(*)=1 from private.cashbook_alerts),'Correction must queue low-stock alert');
 perform pg_temp.check_change((select amount_cents=2000 and record_amount_cents=7000 and entry_type='correction' from private.cashbook_entries where id=current_id),'Correction shape incorrect');
 perform pg_temp.check_change((select (e->>'canManage')::boolean from jsonb_array_elements(result->'entries') e where e->>'id'=current_id::text),'Own current correction is not editable');
 perform pg_temp.check_change((select e->>'canManage'='false' and e->>'superseded'='true' from jsonb_array_elements(result->'entries') e where e->>'id'=original::text),'Stale original remains editable');
 result:=public.cashbook_request(trainer.suite_user_id,edit);
 perform pg_temp.check_change(result->>'entryId'=current_id::text and (select count(*)=3 from private.cashbook_entries),'Retry duplicated correction');
 result:=public.cashbook_request(trainer.suite_user_id,edit||jsonb_build_object('amountCents',6000));
 perform pg_temp.check_change(result->>'status'='409','Changed retry accepted');
 result:=public.cashbook_request(trainer.suite_user_id,jsonb_build_object('action','authorize_change','id',original,'requestId',edit->>'requestId','changeAction','edit'));
 perform pg_temp.check_change(result->'entry'->>'id'=original::text,'Retry preauthorization must work after supersession');
 result:=public.cashbook_request(trainer.suite_user_id,edit||jsonb_build_object('requestId',gen_random_uuid()));
 perform pg_temp.check_change(result->>'status'='409','Stale revision changed twice');
 edit:=edit||jsonb_build_object('id',current_id,'requestId',gen_random_uuid(),'amountCents',2000,'reason','Zu hoch erfasst');
 edit:=edit||jsonb_build_object('signaturePath',trainer.id::text||'/'||(edit->>'requestId')||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,edit);prior_id:=current_id;current_id:=(result->>'entryId')::uuid;
 perform pg_temp.check_change(result->>'balanceCents'='8000','Decreasing withdrawal did not return only difference');
 perform pg_temp.check_change((select not low_alert_active from private.cashbook_safe),'Correction did not rearm alert');
 edit:=edit||jsonb_build_object('id',current_id,'requestId',gen_random_uuid(),'note','Nur Text korrigiert','reason','Spiel korrigiert');
 edit:=edit||jsonb_build_object('signaturePath',trainer.id::text||'/'||(edit->>'requestId')||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,edit);current_id:=(result->>'entryId')::uuid;
 perform pg_temp.check_change(result->>'balanceCents'='8000' and (select amount_cents=0 from private.cashbook_entries where id=current_id),'Text-only change moves money');
 -- Another trainer's receipt may never be reused by a correction.
 booking:=booking||jsonb_build_object('requestId',gen_random_uuid(),'amountCents',1000,'evidenceHash',repeat('e',64));
 booking:=booking||jsonb_build_object('evidencePath',other.id::text||'/'||(booking->>'requestId')||'/photo','signaturePath',other.id::text||'/'||(booking->>'requestId')||'/signature');
 perform public.cashbook_request(other.suite_user_id,booking);
 edit:=edit||jsonb_build_object('id',current_id,'requestId',gen_random_uuid(),'evidenceHash',repeat('e',64));
 edit:=edit||jsonb_build_object('evidencePath',trainer.id::text||'/'||(edit->>'requestId')||'/photo','signaturePath',trainer.id::text||'/'||(edit->>'requestId')||'/signature');
 result:=public.cashbook_request(trainer.suite_user_id,edit);
 perform pg_temp.check_change(result->>'status'='409','Another receipt reused in correction');
 cancellation:=jsonb_build_object('action','cancel','id',current_id,'requestId',gen_random_uuid(),'reason','Doppelt erfasst','confirmed',true,'signatureHash',repeat('f',64));
 cancellation:=cancellation||jsonb_build_object('signaturePath',trainer.id::text||'/'||(cancellation->>'requestId')||'/signature');
 result:=public.cashbook_request(other.suite_user_id,cancellation);
 perform pg_temp.check_change(result->>'status'='403','Foreign trainer cancelled a booking');
 result:=public.cashbook_request(trainer.suite_user_id,cancellation);prior_id:=current_id;current_id:=(result->>'entryId')::uuid;
 perform pg_temp.check_change(result->>'balanceCents'='9000','Cancellation must return latest effective withdrawal, not original amount');
 perform pg_temp.check_change((select record_amount_cents=0 and amount_cents=2000 and entry_type='cancellation' from private.cashbook_entries where id=current_id),'Cancellation shape incorrect');
 perform pg_temp.check_change((select e->>'canManage'='false' from jsonb_array_elements(result->'entries') e where e->>'id'=current_id::text),'Cancelled entry remains editable');
 result:=public.cashbook_request(trainer.suite_user_id,cancellation);
 perform pg_temp.check_change(result->>'balanceCents'='9000','Cancellation retry duplicated balance');
 result:=public.cashbook_request(trainer.suite_user_id,cancellation||jsonb_build_object('reason','Different'));
 perform pg_temp.check_change(result->>'status'='409','Changed cancellation retry accepted');
 result:=public.cashbook_request(trainer.suite_user_id,cancellation||jsonb_build_object('id',current_id,'requestId',gen_random_uuid()));
 perform pg_temp.check_change(result->>'status'='409','Cancellation can be cancelled again');
 perform pg_temp.check_change((select amount_cents=5000 and note='Original' and evidence_hash=repeat('b',64) from private.cashbook_entries where id=original),'Original evidence or amount changed');
 -- Rebinding an account does not confer ownership of its historical records.
 update private.cashbook_accounts set suite_user_id=null where id=other.id;
 update private.cashbook_accounts set suite_user_id=other.suite_user_id where id=trainer.id;
 result:=public.cashbook_request(other.suite_user_id,jsonb_build_object('action','authorize_change','id',original,'requestId',gen_random_uuid(),'changeAction','edit'));
 perform pg_temp.check_change(result->>'status'='403','Rebinding account transfers historical ownership');
end $$;
reset role;
rollback;
